import { benchPokemonFromZone, getBlockedPokemonPlacementIndices } from '../../game/store/prefabs/bench-play-reactions';
import { PokemonCard, pokemonHasCardType } from '../../game/store/card/pokemon-card';
import { Stage, CardType, CardTag, SuperType, EnergyType } from '../../game/store/card/card-types';
import { GameMessage, StoreLike, State, StateUtils } from '../../game';
import { ChooseCardsPrompt } from '../../game/store/prompts/choose-cards-prompt';
import { Effect } from '../../game/store/effects/effect';
import { WAS_ATTACK_USED, ATTACH_ENERGY_PROMPT } from '../../game/store/prefabs/prefabs';
import { PlayerType, SlotType } from '../../game/store/actions/play-card-action';
import { EnergyCard } from '../../game/store/card/energy-card';

export class VaporeonVmax extends PokemonCard {
  public tags = [CardTag.POKEMON_VMAX, CardTag.RAPID_STRIKE];
  public stage: Stage = Stage.VMAX;
  public evolvesFrom: string = 'Vaporeon V';
  public cardType: CardType = W;
  public hp: number = 320;
  public weakness = [{ type: L }];
  public retreat = [C, C];

  public attacks = [
    {
      name: 'Bubble Pod',
      cost: [C],
      damage: 0,
      text: 'Put a Water Pokémon from your discard pile onto your Bench. If you do, attach up to 3 [W] Energy cards from your discard pile to that Pokémon.'
    },
    {
      name: 'Max Torrent',
      cost: [W, C, C],
      damage: 100,
      damageCalculation: '+' as '+',
      text: 'If your opponent\'s Active Pokémon already has any damage counters on it, this attack does 100 more damage.'
    }
  ];

  public regulationMark: string = 'E';
  public set: string = 'EVS';
  public setNumber: string = '30';
  public cardImage: string = 'assets/cardback.png';
  public name: string = 'Vaporeon VMAX';
  public fullName: string = 'Vaporeon VMAX EVS';

  public reduceEffect(store: StoreLike, state: State, effect: Effect): State {
    // Attack 1: Bubble Pod
    // Ref: set-burning-shadows/ho-oh-gx.ts (put Pokemon from discard to bench),
    //      set-darkness-ablaze/blaziken.ts (ATTACH_ENERGY_PROMPT from discard to specific slot)
    if (WAS_ATTACK_USED(effect, 0, this)) {
      const player = effect.player;

      // Check for open bench slots
      const openSlots = player.bench.filter(b => b.cards.length === 0);
      if (openSlots.length === 0) {
        return state;
      }

      const nonWater = player.discard.cards.flatMap((card, index) =>
        card instanceof PokemonCard && pokemonHasCardType(card, CardType.WATER) ? [] : [index]);
      const blocked = getBlockedPokemonPlacementIndices(store, state, player, player.discard, nonWater);
      if (blocked.length === player.discard.cards.length) {
        return state;
      }

      // Let player choose which Water Pokemon to bench
      return store.prompt(state, new ChooseCardsPrompt(
        player,
        GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
        player.discard,
        { superType: SuperType.POKEMON },
        { min: 1, max: 1, allowCancel: false, blocked }
      ), selected => {
        const cards = selected || [];
        if (cards.length === 0) {
          return;
        }

        benchPokemonFromZone(store, state, player, player.discard, cards, openSlots, benchSlot => {
          const hasWaterEnergy = player.discard.cards.some(card =>
            card instanceof EnergyCard && card.energyType === EnergyType.BASIC && card.provides.includes(CardType.WATER));
          if (!hasWaterEnergy) return;

          ATTACH_ENERGY_PROMPT(
            store, state, player,
            PlayerType.BOTTOM_PLAYER, SlotType.DISCARD,
            [SlotType.BENCH],
            { superType: SuperType.ENERGY, energyType: EnergyType.BASIC, name: 'Water Energy' },
            { min: 0, max: 3, allowCancel: false, blockedTo: player.bench
              .map((_, index) => ({ player: PlayerType.BOTTOM_PLAYER, slot: SlotType.BENCH, index }))
              .filter(target => player.bench[target.index] !== benchSlot) }
          );
        });
      });
    }

    // Attack 2: Max Torrent
    // Ref: AGENTS-patterns.md (+X if already damaged)
    if (WAS_ATTACK_USED(effect, 1, this)) {
      const opponent = StateUtils.getOpponent(state, effect.player);
      if (opponent.active.damage > 0) {
        effect.damage += 100;
      }
    }

    return state;
  }
}
